package middleware

import (
	"net/http"
	"net/http/httptest"
	"net/url"
	"testing"

	"github.com/labstack/echo/v4"
)

func TestZZVerifyProxyBalancerWithNoTargets(t *testing.T) {
	// (a) Next() on balancers built with no targets must return nil and not panic.
	if got := NewRandomBalancer(nil).Next(nil); got != nil {
		t.Fatalf("random balancer Next() = %v, want nil", got)
	}
	if got := NewRoundRobinBalancer(nil).Next(nil); got != nil {
		t.Fatalf("round robin balancer Next() = %v, want nil", got)
	}

	serve := func(t *testing.T, b ProxyBalancer) *httptest.ResponseRecorder {
		t.Helper()
		e := echo.New()
		e.Use(Proxy(b))
		e.Any("/", func(c echo.Context) error { return c.NoContent(http.StatusOK) })
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		return rec
	}

	// (b) serving a request through the proxy middleware must not panic and must yield 503.
	for name, b := range map[string]ProxyBalancer{
		"random":     NewRandomBalancer(nil),
		"roundRobin": NewRoundRobinBalancer(nil),
	} {
		rec := serve(t, b)
		if rec.Code != http.StatusServiceUnavailable {
			t.Fatalf("%s: status = %d, want %d", name, rec.Code, http.StatusServiceUnavailable)
		}
	}

	// (c) balancer created with targets, then all targets removed -> 503, no panic.
	u, err := url.Parse("http://127.0.0.1:1")
	if err != nil {
		t.Fatal(err)
	}
	for name, b := range map[string]ProxyBalancer{
		"random":     NewRandomBalancer([]*ProxyTarget{{Name: "t1", URL: u}}),
		"roundRobin": NewRoundRobinBalancer([]*ProxyTarget{{Name: "t1", URL: u}}),
	} {
		if !b.RemoveTarget("t1") {
			t.Fatalf("%s: RemoveTarget returned false", name)
		}
		if got := b.Next(nil); got != nil {
			t.Fatalf("%s: Next() after removing all targets = %v, want nil", name, got)
		}
		rec := serve(t, b)
		if rec.Code != http.StatusServiceUnavailable {
			t.Fatalf("%s: status after removing all targets = %d, want %d", name, rec.Code, http.StatusServiceUnavailable)
		}
	}
}

