// ---- oracle ----

type patSeg struct {
	kind int // 0 static, 1 param, 2 any
	text string
}

func parsePattern(p string) []patSeg {
	parts := strings.Split(p, "/")
	segs := make([]patSeg, 0, len(parts))
	for _, s := range parts {
		switch {
		case s == "*":
			segs = append(segs, patSeg{2, "*"})
		case strings.HasPrefix(s, ":"):
			segs = append(segs, patSeg{1, s[1:]})
		default:
			segs = append(segs, patSeg{0, s})
		}
	}
	return segs
}

func matchPattern(segs []patSeg, path string) (map[string]string, bool) {
	parts := strings.Split(path, "/")
	params := map[string]string{}
	i := 0
	for si, seg := range segs {
		switch seg.kind {
		case 0:
			if i >= len(parts) || parts[i] != seg.text {
				return nil, false
			}
			i++
		case 1:
			if i >= len(parts) {
				return nil, false
			}
			if i == len(parts)-1 && parts[i] == "" {
				return nil, false
			}
			params[seg.text] = parts[i]
			i++
		case 2:
			if si != len(segs)-1 || i >= len(parts) {
				return nil, false
			}
			params["*"] = strings.Join(parts[i:], "/")
			i = len(parts)
		}
	}
	if i != len(parts) {
		return nil, false
	}
	return params, true
}

func oracle(routes []string, path string) (string, map[string]string, bool) {
	var best []patSeg
	var bestParams map[string]string
	for _, rt := range routes {
		segs := parsePattern(rt)
		params, ok := matchPattern(segs, path)
		if !ok {
			continue
		}
		if best == nil || lessKinds(segs, best) {
			best = segs
			bestParams = params
		}
	}
	if best == nil {
		return "", nil, false
	}
	return strings.Join(kindStrings(best), ""), bestParams, true
}

func kindStrings(segs []patSeg) []string {
	out := make([]string, len(segs))
	for i, s := range segs {
		out[i] = fmt.Sprint(s.kind)
	}
